{"hypotheses": [
  {
    "name": "Analyst Disagreement Plus Unexpected R&D",
    "mechanism": "Combining high analyst EPS forecast dispersion with unexpected R&D surges captures stocks where information uncertainty and innovation surprises coincide. This joint exposure is hypothesized to exploit situations where true firm prospects are underestimated by the market due to noisy signals and ambiguous news, creating an inefficiency beyond each primitive alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "SurpriseRD"},
        {"weight": -0.5, "primitive": "DownRecomm"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Organizational Capital with Seasonality Filter",
    "mechanism": "Firms with high organizational capital outperform especially when typical calendar-based return seasonality is weak, reflecting that complex, knowledge-intensive firms are less affected by herd-driven flows and more by persistent operational edge. The composite times exposure to org capital by avoiding strong seasonal effects, extracting a unique premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -1.0, "primitive": "MomSeason"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "MomSeason", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Low Leverage Plus Deferred Revenue Growth",
    "mechanism": "Firms with low leverage and rising deferred revenue signal low risk and strong future cash inflows. The combination targets companies funding growth with customer prepayments, not debt, which is a uniquely high-quality growth profile not captured by either signal alone.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "Leverage"},
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": 0.5, "primitive": "CBOperProf"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Customer Momentum and Patent Intensity",
    "mechanism": "Stocks of firms whose customers have strong momentum and whose patent output is high benefit from positive network spillovers and innovation diffusion. This interaction is distinct from either customer or innovation alpha alone, as it exploits the propagation channel in supply chains.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "PatentsRD"},
        {"weight": -0.5, "primitive": "DebtIssuance"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "PatentsRD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Put-Call Volatility Slope and Asset Growth Negation",
    "mechanism": "A steep put-call implied volatility slope typically reflects downside risk aversion; subtracting asset growth exposure isolates situations where crowding in 'safe growers' distorts option markets, creating reversals when pessimism is overdone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "SmileSlope"},
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Pension Funding and Real Estate Holdings",
    "mechanism": "Firms with well-funded pensions and substantial real estate assets should be less exposed to liability-driven selling and benefit from inflationary tailwinds, producing a differentiated return stream from each component. Their joint presence signals defensive asset backing plus efficient liability management.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "FR"},
        {"weight": 1.0, "primitive": "realestate"},
        {"weight": -0.5, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "FR", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Option/Stock Volume Ratio and Cash Productivity",
    "mechanism": "Stocks with high option to stock trading volume but strong cash productivity are likely under the radar of options traders, implying that liquidity-driven dislocations (from derivatives) are more likely to revert in fundamentally cash-rich firms. This composite exploits the interplay between speculative flow and operational strength.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OptionVolume1"},
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": -1.0, "primitive": "IdioVol3F"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "OptionVolume1", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Forecast Error and Change in Taxes",
    "mechanism": "Stocks with large predicted analyst forecast errors and rising tax payments signal positive earnings surprises that analysts systematically underappreciate. This blend captures a behavioral bias in earnings forecasting tied to real cash-tax evidence, distinct from either input alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "PredictedFE"},
        {"weight": 1.0, "primitive": "ChTax"},
        {"weight": -0.5, "primitive": "ShareIss1Y"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 15
  }
]}
